"""Arithmetic expression evaluator.

Implements a hand-written tokenizer and recursive-descent parser reproducing
Python's arithmetic semantics for + - * / % ** with parentheses and stacked
unary +/-.  No use of eval/exec/ast/compile.
"""

import re

__all__ = ["evaluate"]

_NUMBER_RE = re.compile(r"\d+\.\d*|\.\d+|\d+")
_SKIP = " \t\r\n\f\v"

# Token kinds
_NUM = "NUM"
_OP = "OP"
_LPAR = "LPAR"
_RPAR = "RPAR"


def _tokenize(expr):
    """Turn *expr* into a list of (kind, value) tuples.

    Raises ValueError on any character that cannot start a valid token.
    """
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch in _SKIP:
            i += 1
            continue
        if ch == "(":
            tokens.append((_LPAR, "("))
            i += 1
            continue
        if ch == ")":
            tokens.append((_RPAR, ")"))
            i += 1
            continue
        if ch == "*":
            if expr.startswith("**", i):
                tokens.append((_OP, "**"))
                i += 2
            else:
                tokens.append((_OP, "*"))
                i += 1
            continue
        if ch in "+-/%":
            tokens.append((_OP, ch))
            i += 1
            continue
        if ch.isdigit() or ch == ".":
            m = _NUMBER_RE.match(expr, i)
            if m is None:
                raise ValueError("malformed number at position %d" % i)
            text = m.group(0)
            try:
                value = float(text)
            except (ValueError, OverflowError):
                raise ValueError("malformed number %r" % text)
            tokens.append((_NUM, value))
            i = m.end()
            continue
        raise ValueError("invalid character %r at position %d" % (ch, i))

    return tokens


class _Parser(object):
    """Recursive-descent parser.

    Grammar (lowest to highest precedence)::

        expr   := term (('+' | '-') term)*
        term   := power (('*' | '/' | '%') power)*   -- with unary handled below
        unary  := ('+' | '-') unary | power
        power  := atom ('**' unary)?
        atom   := NUMBER | '(' expr ')'

    ``term`` actually parses ``unary`` operands, which makes unary minus bind
    tighter than ``*``/``/``/``%`` but looser than ``**`` on its left, while
    ``power``'s right operand being ``unary`` allows ``2**-1``.
    """

    def __init__(self, tokens):
        self._tokens = tokens
        self._pos = 0

    # -- token helpers -------------------------------------------------
    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return (None, None)

    def _advance(self):
        tok = self._tokens[self._pos]
        self._pos += 1
        return tok

    def _at_end(self):
        return self._pos >= len(self._tokens)

    # -- grammar rules -------------------------------------------------
    def parse(self):
        if not self._tokens:
            raise ValueError("empty expression")
        value = self._parse_expr()
        if not self._at_end():
            kind, val = self._peek()
            if kind == _RPAR:
                raise ValueError("unbalanced parentheses: unexpected ')'")
            raise ValueError("unexpected token %r" % (val,))
        return value

    def _parse_expr(self):
        value = self._parse_term()
        while True:
            kind, val = self._peek()
            if kind == _OP and val in ("+", "-"):
                self._advance()
                right = self._parse_term()
                if val == "+":
                    value = value + right
                else:
                    value = value - right
            else:
                return value

    def _parse_term(self):
        value = self._parse_unary()
        while True:
            kind, val = self._peek()
            if kind == _OP and val in ("*", "/", "%"):
                self._advance()
                right = self._parse_unary()
                if val == "*":
                    value = value * right
                elif val == "/":
                    if right == 0.0:
                        raise ZeroDivisionError("float division by zero")
                    value = value / right
                else:
                    if right == 0.0:
                        raise ZeroDivisionError("float modulo by zero")
                    value = value % right
            else:
                return value

    def _parse_unary(self):
        kind, val = self._peek()
        if kind == _OP and val in ("+", "-"):
            self._advance()
            operand = self._parse_unary()
            return -operand if val == "-" else +operand
        return self._parse_power()

    def _parse_power(self):
        base = self._parse_atom()
        kind, val = self._peek()
        if kind == _OP and val == "**":
            self._advance()
            # Right operand parsed as ``unary`` => right-associative and
            # permits a unary sign directly after '**'.
            exponent = self._parse_unary()
            return base ** exponent
        return base

    def _parse_atom(self):
        if self._at_end():
            raise ValueError("unexpected end of expression")
        kind, val = self._advance()
        if kind == _NUM:
            return val
        if kind == _LPAR:
            if self._at_end():
                raise ValueError("unbalanced parentheses: missing ')'")
            if self._peek()[0] == _RPAR:
                raise ValueError("empty parentheses")
            value = self._parse_expr()
            if self._at_end() or self._peek()[0] != _RPAR:
                raise ValueError("unbalanced parentheses: missing ')'")
            self._advance()
            return value
        if kind == _RPAR:
            raise ValueError("unbalanced parentheses: unexpected ')'")
        raise ValueError("unexpected operator %r" % (val,))


def evaluate(expr):
    """Evaluate the arithmetic expression *expr* and return a float.

    Supports ``+ - * / % **``, parentheses, stacked unary ``+``/``-`` and
    integer/decimal literals.  Raises ``ValueError`` for malformed input and
    ``ZeroDivisionError`` for division or modulo by zero.
    """
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")
    result = _Parser(tokens).parse()
    return float(result)

opus-solo.cron_next:
"""Minimal 5-field cron expression evaluator.

Public API::

    cron_next(expr: str, after: datetime) -> datetime

Returns the earliest datetime strictly after ``after`` matching ``expr``.
Standard library only.
"""

from datetime import datetime, timedelta

__all__ = ["cron_next"]


_FIELD_BOUNDS = (
    (0, 59),   # minute
    (0, 23),   # hour
    (1, 31),   # day of month
    (1, 12),   # month
    (0, 6),    # day of week, 0 = Sunday
)


def _parse_int(text):
    """Parse a bare non-negative decimal integer, else raise ValueError."""
    if not text or not text.isdigit():
        raise ValueError("invalid cron number: %r" % (text,))
    return int(text)


def _parse_item(item, lo, hi):
    """Expand one comma-separated cron item into a set of ints."""
    if not item:
        raise ValueError("empty cron item")

    step = 1
    base = item
    if "/" in item:
        parts = item.split("/")
        if len(parts) != 2:
            raise ValueError("malformed step in cron item: %r" % (item,))
        base, step_text = parts
        step = _parse_int(step_text)
        if step < 1:
            raise ValueError("cron step must be >= 1: %r" % (item,))
        if base != "*" and "-" not in base:
            raise ValueError("step on a single value is invalid: %r" % (item,))

    if base == "*":
        start, end = lo, hi
    elif "-" in base:
        parts = base.split("-")
        if len(parts) != 2:
            raise ValueError("malformed range in cron item: %r" % (item,))
        start = _parse_int(parts[0])
        end = _parse_int(parts[1])
        if start > end:
            raise ValueError("range start after end: %r" % (item,))
    else:
        start = end = _parse_int(base)

    if start < lo or start > hi or end < lo or end > hi:
        raise ValueError("cron value out of range [%d,%d]: %r" % (lo, hi, item))

    return set(range(start, end + 1, step))


def _parse_field(field, lo, hi):
    """Expand one whitespace-delimited cron field into a set of ints."""
    if not field:
        raise ValueError("empty cron field")
    values = set()
    for item in field.split(","):
        values |= _parse_item(item.strip(), lo, hi)
    if not values:
        raise ValueError("cron field matches nothing: %r" % (field,))
    return values


def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError("cron expression must be a string")
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")
    sets = [
        _parse_field(f, lo, hi)
        for f, (lo, hi) in zip(fields, _FIELD_BOUNDS)
    ]
    dom_restricted = fields[2].strip() != "*"
    dow_restricted = fields[4].strip() != "*"
    return sets, dom_restricted, dow_restricted


def _day_matches(moment, doms, dows, dom_restricted, dow_restricted):
    dom_hit = moment.day in doms
    dow_hit = ((moment.weekday() + 1) % 7) in dows
    if dom_restricted and dow_restricted:
        return dom_hit or dow_hit
    if dom_restricted:
        return dom_hit
    if dow_restricted:
        return dow_hit
    return True


def _next_day(moment):
    return (moment + timedelta(days=1)).replace(hour=0, minute=0)


def cron_next(expr, after):
    """Earliest datetime strictly after ``after`` matching the cron ``expr``."""
    (minutes, hours, doms, months, dows), dom_r, dow_r = _parse(expr)

    if not isinstance(after, datetime):
        raise ValueError("after must be a datetime")

    moment = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    horizon = after + timedelta(days=366 * 5 + 2)
    while moment <= horizon:
        if moment.month not in months:
            # Jump to the first minute of the next month.
            if moment.month == 12:
                moment = moment.replace(
                    year=moment.year + 1, month=1, day=1, hour=0, minute=0
                )
            else:
                moment = moment.replace(
                    month=moment.month + 1, day=1, hour=0, minute=0
                )
            continue

        if not _day_matches(moment, doms, dows, dom_r, dow_r):
            moment = _next_day(moment)
            continue

        if moment.hour not in hours:
            nxt = [h for h in hours if h > moment.hour]
            if not nxt:
                moment = _next_day(moment)
            else:
                moment = moment.replace(hour=min(nxt), minute=0)
            continue

        if moment.minute not in minutes:
            nxt = [m for m in minutes if m > moment.minute]
            if not nxt:
                if moment.hour == 23:
                    moment = _next_day(moment)
                else:
                    moment = moment.replace(hour=moment.hour + 1, minute=0)
            else:
                moment = moment.replace(minute=min(nxt))
            continue

        return moment

    raise ValueError("no matching time found within 5 years")

opus-solo.wrap_text:
"""Greedy, paragraph-aware text wrapping.

Public API: ``wrap_text(text, width)``.
Implemented without the ``textwrap`` module.
"""

__all__ = ["wrap_text"]


def _split_paragraphs(text):
    """Split ``text`` into paragraphs on blank (empty/whitespace-only) lines.

    Returns a list of word-lists; empty paragraphs are dropped, so runs of
    blank lines collapse into a single break and leading/trailing blank
    lines produce nothing.
    """
    paragraphs = []
    current = []
    for line in text.splitlines():
        if line.strip() == "":
            if current:
                paragraphs.append(current)
                current = []
        else:
            current.extend(line.split())
    if current:
        paragraphs.append(current)
    return paragraphs


def _wrap_paragraph(words, width):
    """Greedily wrap a list of words into lines of at most ``width`` chars."""
    lines = []
    line = ""
    for word in words:
        while len(word) > width:
            # Overlong word: finish the current line, then hard-break.
            if line:
                lines.append(line)
                line = ""
            lines.append(word[:width])
            word = word[width:]
        if not word:
            continue
        if not line:
            line = word
        elif len(line) + 1 + len(word) <= width:
            line += " " + word
        else:
            lines.append(line)
            line = word
    if line:
        lines.append(line)
    return lines


def wrap_text(text: str, width: int) -> str:
    """Wrap ``text`` to ``width`` columns, preserving paragraph breaks.

    Paragraphs are separated by blank lines in the input and by exactly one
    empty line in the output. Within a paragraph all whitespace collapses and
    words are packed greedily. Words longer than ``width`` are hard-broken
    into ``width``-sized chunks.

    Raises:
        ValueError: if ``width`` is less than 1.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    out = []
    for words in _split_paragraphs(text):
        lines = _wrap_paragraph(words, width)
        if lines:
            out.append("\n".join(lines))
    return "\n\n".join(out)
